class Solution {
public:
    int twoSumLessThanK(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int left = 0;
        int right = static_cast<int>(nums.size()) - 1;
        int answer = -1;
        while (left < right) {
            int sum = nums[left] + nums[right];
            if (sum < k) {
                answer = max(answer, sum);
                ++left;
            } else {
                --right;
            }
        }
        return answer;
    }
};
